INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15301, 'Psalms 142:3', 'Psalms', 142, 3, '&nbsp;کله چې زما روح په ما کښې کمزورے شى، نو دا تۀ يې چې زما په لارو پوهېږې. په کومو لارو چې زۀ روان يم نو په هغه لارو کښې يې ما دپاره دام پټ لګولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15302, 'Psalms 142:4', 'Psalms', 142, 4, '&nbsp;وګوره زما ښې طرف ته وګوره هيڅوک زما پرواه نۀ کوى، زما پناه ګاه نشته هيڅوک زما د ژوند پرواه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15303, 'Psalms 142:5', 'Psalms', 142, 5, '&nbsp;زۀ تا ته ژړا کوم، اے مالِکه خُدايه، زۀ دا وايم چې، ”تۀ زما پناه ګاه يې، او تۀ د ژوندون په دُنيا کښې زما برخه يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15304, 'Psalms 142:6', 'Psalms', 142, 6, '&nbsp;زما ژړا تۀ واوره، ځکه چې زۀ ډېر سخت محتاجه يم. څوک چې ما ګېرول غواړى د هغوئ نه ما بچ کړه، ځکه چې دوئ زما نه ډېر زورَور دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15305, 'Psalms 142:7', 'Psalms', 142, 7, '&nbsp;تۀ ما د قېد نه خلاص کړه، چې ستا د نوم ثناء صِفت وکړم. نو بيا به صادقان رايوځائ شى زما په حقله، ځکه ستا د مهربانۍ په وجه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15306, 'Psalms 143:1', 'Psalms', 143, 1, '&nbsp;اے مالِکه خُدايه، زما دُعا واوره، زما ژړا ته د رحم دپاره غوږ ونيسه، په خپله وفادارۍ او صداقت سره دې زما مدد دپاره راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15307, 'Psalms 143:2', 'Psalms', 143, 2, '&nbsp;او خپل خِدمتګار دې د عدالت دپاره مۀ راوله، ځکه چې ستا په وړاندې څوک هم بې‌ګناه نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15308, 'Psalms 143:3', 'Psalms', 143, 3, '&nbsp;دشمن راپسې لګېدلے دے ما په زمکه ښکته غورزوى، هغۀ زۀ په زور په تورو تيارو کښې اوسولم لکه د هغه خلقو چې ډېر مخکښې مړۀ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15309, 'Psalms 143:4', 'Psalms', 143, 4, '&nbsp;نو ځکه روح مې په بدن کښې کمزورے کيږى، نو دغه شان د يرې نه زما زړۀ په ما کښې ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15310, 'Psalms 143:5', 'Psalms', 143, 5, '&nbsp;کله چې زۀ پخوانى وختونه رايادوم، نو زۀ ستا په کارونو سوچ کوم، کوم کارونه چې ستا لاسونو کړى دى په هغوئ فکر کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15311, 'Psalms 143:6', 'Psalms', 143, 6, '&nbsp;زۀ تا ته د دُعا دپاره لاسونه پورته کوم، زما ځان لکه د للمې زمکې ستا تږے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15312, 'Psalms 143:7', 'Psalms', 143, 7, '&nbsp;اے مالِکه خُدايه، ما ته زر جواب راکړه، زۀ نااُميده شوے يم. ما نه خپل مخ مۀ اړوه، نو ګنې زۀ به د هغوئ په شان شم څوک چې ښکته قبر ته روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15313, 'Psalms 143:8', 'Psalms', 143, 8, '&nbsp;سحر دې ستا د تل عُمرى مينې کلام راوړى، ځکه چې زۀ په تا باندې يقين لرم. ما ته هغه لار راوښايه چې زۀ پرې لاړ شم، ځکه چې تا ته ما خپل ځان په دُعا کښې پورته کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15314, 'Psalms 143:9', 'Psalms', 143, 9, '&nbsp;ما د خپلو دشمنانو نه خلاص کړه، اے مالِکه خُدايه، ځکه چې زۀ د پناه دپاره تا ته را زغلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15315, 'Psalms 143:10', 'Psalms', 143, 10, '&nbsp;ستا د رضا پوره کولو ما ته تعليم راکړه، ځکه چې تۀ زما خُدائ پاک يې. ستا نېک روح دې په هوار مېدان کښې زما رهنمائى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15316, 'Psalms 143:11', 'Psalms', 143, 11, '&nbsp;د خپل نوم په خاطر دې، مالِک خُدايه، زما ژوند بچ کړه. په خپل صداقت دې ما تکليفونو نه راوباسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15317, 'Psalms 143:12', 'Psalms', 143, 12, '&nbsp;تۀ ما سره د خپلې نۀ ختمېدونکې مينې په وجه زما دشمنان خاموشه کړه، زما ټول دشمنان تباه کړه، ځکه چې زۀ ستا خِدمتګار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15318, 'Psalms 144:1', 'Psalms', 144, 1, '&nbsp;مالِک خُدائ ته دې ثناء صِفت وى څوک چې زما ګټ دے، څوک چې زما لاسونه د جنګ دپاره تياروى، او زما ګوتې د جنګ دپاره تياروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15319, 'Psalms 144:2', 'Psalms', 144, 2, '&nbsp;هغه زما مينه ناک خُدائ پاک او د حِفاظت قلعه ده، هغه زما پناه ګاه او زما خلاصونکے دے، هغه زما ډال دے په چا کښې چې زۀ پناه اخلم، څوک چې خلق زما د اختيار لاندې راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15320, 'Psalms 144:3', 'Psalms', 144, 3, '&nbsp;اے مالِکه خُدايه، انسان څۀ دے چې تۀ يې خيال ساتې، د انسان زوئ څۀ دے چې تۀ يې فکر کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15321, 'Psalms 144:4', 'Psalms', 144, 4, '&nbsp;انسان دے لکه د هوا په شان، د هغۀ عمر تېريږى لکه سورى په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15322, 'Psalms 144:5', 'Psalms', 144, 5, '&nbsp;خپل آسمانونه وشلوه اے مالِکه خُدايه او لاندې راکوز شه، غرونو ته صرف لاس وروړه نو دوئ به لوګے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15323, 'Psalms 144:6', 'Psalms', 144, 6, '&nbsp;برېښنا ګانې راولېږه او دشمنان خوارۀ کړه، او خپل غشى پرې راووروه او هغوئ تس نس کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15324, 'Psalms 144:7', 'Psalms', 144, 7, '&nbsp;د بره نه خپل لاس راوغزوه، ما ته تحفُظ او خلاصون راکړه، د زورَورو اوبو او د غېرو لاسونو نه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15325, 'Psalms 144:8', 'Psalms', 144, 8, '&nbsp;د چا خولۀ چې د دروغو نه ډکه ده، د چا لاسونه چې دوکه باز دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15326, 'Psalms 144:9', 'Psalms', 144, 9, '&nbsp;زۀ به تا ته نوے حمد ووايم، اے پاکه خُدايه، په لس تاريزه سريندې به زۀ تا ته سُر ساز وغږوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15327, 'Psalms 144:10', 'Psalms', 144, 10, '&nbsp;هغه چا ته څوک چې بادشاهانو له فتح ورکوى، څوک چې خپل خِدمتګار داؤد ته د وژونکې تُورې نه خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15328, 'Psalms 144:11', 'Psalms', 144, 11, '&nbsp;ما ته تحفُظ او ما ته خلاصون راکړه، او د غېرو د لاسونو نه خلاصون راکړه، د چا خولۀ چې د دروغو نه ډکه ده، او د چا لاسونه چې دوکه باز دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15329, 'Psalms 144:12', 'Psalms', 144, 12, '&nbsp;نو بيا به زمونږ زامن په ځوانۍ کښې لکه د سيرابه تکو شنو بوټو په شان وى، او زمونږ لوڼه به لکه د محل د زينت د ستنو په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15330, 'Psalms 144:13', 'Psalms', 144, 13, '&nbsp;زمونږ ګودامونه به د هر قسمه غلې نه ډک وى، زمونږ ګډې به زرګونو ته ورسيږى، په زرګونو به زمونږ په پټو کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15331, 'Psalms 144:14', 'Psalms', 144, 14, '&nbsp;زمونږ غوَيان به درانۀ بارونه وړى، نو زمونږ د ښار دېوالونه به کنډر نۀ شى، هيڅ څوک به قېدى بوتلے نۀ شى، او زمونږ په کوڅو کښې به د نااُميدۍ ژړا نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15332, 'Psalms 144:15', 'Psalms', 144, 15, '&nbsp;بختور دى هغه خلق د چا په حقله چې دا رښتيا وى، بختور دى هغه خلق د چا چې خُدائ پاک، مالِک خُدائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15333, 'Psalms 145:1', 'Psalms', 145, 1, '&nbsp;اے زما پاکه خُدايه، بادشاه، زۀ به ستا لوئى بيانوم، او زۀ به د تل دپاره ستا د نوم ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15334, 'Psalms 145:2', 'Psalms', 145, 2, '&nbsp;زۀ به هره ورځ ستا ثناء صِفت وکړم، زۀ به د تل دپاره ستا د نوم لوئى بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15335, 'Psalms 145:3', 'Psalms', 145, 3, '&nbsp;مالِک خُدائ لوئ دے او د ډېر ثناء صِفت قابل دے، د هغۀ لوئى هيڅوک هم معلومولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15336, 'Psalms 145:4', 'Psalms', 145, 4, '&nbsp;يو نسل به بل نسل ته ستا د کارونو ستائينه کوى، او دوئ به ستا د لويئ کارونه بيانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15337, 'Psalms 145:5', 'Psalms', 145, 5, '&nbsp;هغوئ به ستا د جلالى شان او شوکت او د لويئ خبرې کوى، زۀ به ستا په عجيبه کارونو فکر وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15338, 'Psalms 145:6', 'Psalms', 145, 6, '&nbsp;هغوئ به ستا د هيبتناکه کارونو په حقله خبرې وکړى، او زۀ به ستا د لويو کارنامو بيان وکړمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15339, 'Psalms 145:7', 'Psalms', 145, 7, '&nbsp;هغوئ به ستا د بې‌اندازې ښۀ‌والى جشن کوى، او په خوشحالۍ سره به ستا د صداقت سندرې غږوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15340, 'Psalms 145:8', 'Psalms', 145, 8, '&nbsp;مالِک خُدائ رحيم او مهربان دے، زر نۀ په غصه کيږى او ډېره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15341, 'Psalms 145:9', 'Psalms', 145, 9, '&nbsp;مالِک خُدائ د هر چا سره ښۀ دے، او هر څۀ چې هغۀ پېدا کړى دى په هغه ټولو مهربانه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15342, 'Psalms 145:10', 'Psalms', 145, 10, '&nbsp;اے مالِکه خُدايه، ستا مخلوق دې ستا شُکر وکړى، ستا مقدسين دې ستا ثناء صِفت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15343, 'Psalms 145:11', 'Psalms', 145, 11, '&nbsp;دوئ به ستا د بادشاهت د جلال خبرې وکړى، او دوئ به ستا د قدرت خبرې وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15344, 'Psalms 145:12', 'Psalms', 145, 12, '&nbsp;نو چې ستا په طاقتمند کارونو ټول خلق پوهه شى، او ستا د بادشاهت د جلالى شان او شوکت نه خبر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15345, 'Psalms 145:13', 'Psalms', 145, 13, '&nbsp;ستا بادشاهى د تل بادشاهى ده، ستا حکومت په ټولو نسلونو کښې پاتې کېدونکے دے. مالِک خُدائ په خپلو ټولو وعدو وفادار دے، او هغه په خپلو ټولو پېدا کوونکو مِهربانه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15346, 'Psalms 145:14', 'Psalms', 145, 14, '&nbsp;مالِک خُدائ هغوئ ټول اوچتوى څوک چې را‎پرېوځى، او هغه ټول راکونټى شوى راوچته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15347, 'Psalms 145:15', 'Psalms', 145, 15, '&nbsp;او د ټولو سترګې تا ته دى، او تۀ ټولو ته په صحيح وخت کښې خوراک ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15348, 'Psalms 145:16', 'Psalms', 145, 16, '&nbsp;مالِکه خُدايه چې خپل لاس پرانيزې، په خپله د هر يو ژوندى څيز لوږه تنده ختموې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15349, 'Psalms 145:17', 'Psalms', 145, 17, '&nbsp;مالِک خُدائ په خپلو ټولو کارونو کښې صادق دے، او هغه په خپلو ټولو پېدا کوونکو مِهربانه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15350, 'Psalms 145:18', 'Psalms', 145, 18, '&nbsp;مالِک خُدائ هغه ټولو ته نزدې دے څوک چې ورته آواز کوى، هغوئ ټولو ته نزدې دے څوک چې په رښتيا ورته آواز کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15351, 'Psalms 145:19', 'Psalms', 145, 19, '&nbsp;څوک چې د هغۀ نه يريږى د هغوئ ټولو ارمانونه پوره کوى، او هغه د دوئ ژړا اورى او خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15352, 'Psalms 145:20', 'Psalms', 145, 20, '&nbsp;مالِک خُدائ د هغوئ خيال ساتى څوک چې د هغۀ سره مينه کوى، خو هغه به ټول شريران تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15353, 'Psalms 145:21', 'Psalms', 145, 21, '&nbsp;زما خولۀ به د مالِک خُدائ ثناء صِفت کوى، او ټول مخلوق به د هغۀ د مقدس نوم د تل دپاره ثناه صِفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15354, 'Psalms 146:1', 'Psalms', 146, 1, '&nbsp;د مالِک خُدائ ثناء صِفت دې وى. د مالِک خُدائ ثناء صِفت وکړه، اے زما ځانه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15355, 'Psalms 146:2', 'Psalms', 146, 2, '&nbsp;زۀ به په خپل ټول ژوند کښې د مالِک خُدائ ثناء صِفت کوم، او ترڅو چې زۀ ژوندے يم د مالِک خُدائ ثناء صِفت به کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15356, 'Psalms 146:3', 'Psalms', 146, 3, '&nbsp;او په شهزادګانو توکل مۀ کوئ، په فانى انسان توکل مۀ کوئ څوک چې خلاصون نۀ شى ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15357, 'Psalms 146:4', 'Psalms', 146, 4, '&nbsp;کله چې ترې روح وځى نو خاورو سره خاورې شى، او په هم هغه ورځ يې ټولې منصوبې خرابې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15358, 'Psalms 146:5', 'Psalms', 146, 5, '&nbsp;بختور دى هغوئ د چا مدد چې د يعقوب خُدائ پاک وى، او د چا اُميد چې په مالِک خُدائ يعنې په خپل خُدائ پاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15359, 'Psalms 146:6', 'Psalms', 146, 6, '&nbsp;ځکه چې هغۀ آسمانونه او زمکه، سمندر او څۀ چې په کښې دى پېدا کړى دى او هغه تل وفادار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15360, 'Psalms 146:7', 'Psalms', 146, 7, '&nbsp;هغه په خپله د مظلومانو مقدمه چلوى، او اوږى ته خوراک ورکوى. مالِک خُدائ قېديان آزادوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15361, 'Psalms 146:8', 'Psalms', 146, 8, '&nbsp;مالِک خُدائ ړندو ته نظر ورکوى. او هغه ټول راکونټى شوى راوچته وى، مالِک خُدائ د صادقانو سره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15362, 'Psalms 146:9', 'Psalms', 146, 9, '&nbsp;مالِک خُدائ د مسافرو خيال ساتى، او يتيمانو او کونډو ته خوراک ورکوى، خو هغه د بدعملو منصوبې او طريقې خرابوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15363, 'Psalms 146:10', 'Psalms', 146, 10, '&nbsp;مالِک خُدائ د تل دپاره بادشاهت کوى، د ټولو نسلونو دپاره اے صيونه. د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15364, 'Psalms 147:1', 'Psalms', 147, 1, '&nbsp;د مالِک خُدائ ثناء صِفت وکړئ. دا څومره ښه ده چې مونږ د خپل خُدائ پاک ثناء صِفت وکړو، او څومره د خوښې خبره ده چې مونږ د هغۀ ثناء وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15365, 'Psalms 147:2', 'Psalms', 147, 2, '&nbsp;مالِک خُدائ يروشلم بيا آبادوى، هغه د بنى اِسرائيلو شړلى خلق راغونډوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15366, 'Psalms 147:3', 'Psalms', 147, 3, '&nbsp;هغه مات زړونه روغوى، او د هغوئ په زخمونو پټئ لګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15367, 'Psalms 147:4', 'Psalms', 147, 4, '&nbsp;هغۀ ته د ټولو ستورو د شمېر پته ده، او هر يو ستورى ته په نامه آواز کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15368, 'Psalms 147:5', 'Psalms', 147, 5, '&nbsp;زمونږ مالِک خُدائ لوئ او په طاقت کښې زورَور دے، او د هغۀ د پوهې څۀ حد نشته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15369, 'Psalms 147:6', 'Psalms', 147, 6, '&nbsp;مالِک خُدائ د عاجزانو ساتنه کوى، خو شريران زمکې ته راغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15370, 'Psalms 147:7', 'Psalms', 147, 7, '&nbsp;په شُکر ګزارۍ سره د مالِک خُدائ حمد و ثناء ووايئ، او زمونږ خُدائ پاک ته په رباب سره ساز وغږوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15371, 'Psalms 147:8', 'Psalms', 147, 8, '&nbsp;هغه آسمان په وريځو کښې پټوى، او هغه په زمکه بارانونه راوروى، او په غرونو او غونډو واښۀ راشنۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15372, 'Psalms 147:9', 'Psalms', 147, 9, '&nbsp;هغه ځناورو ته خوراک ورکوى، او کارغانو بچو ته کله چې وچغيږى خوراک ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15373, 'Psalms 147:10', 'Psalms', 147, 10, '&nbsp;د هغۀ خوشحالى د آس په طاقت کښې نۀ ده، او نۀ د هغۀ خوشحالى د انسان په طاقت کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15374, 'Psalms 147:11', 'Psalms', 147, 11, '&nbsp;او مالِک د هغوئ نه خوشحاله وى څوک چې د هغۀ نه يريږى، او څوک چې د هغۀ په نۀ ختمېدونکې مينه باندې اُميد ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15375, 'Psalms 147:12', 'Psalms', 147, 12, '&nbsp;د مالِک خُدائ لوئى بيان کړه، اے يروشلمه، د مالِک خُدائ ثناء صِفت ادا کړه، اے صيونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15376, 'Psalms 147:13', 'Psalms', 147, 13, '&nbsp;او هغه ستا د دروازو اړمونه او دُرشلى مضبوطوى، او په تا کښې اوسېدونکو ته برکت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15377, 'Psalms 147:14', 'Psalms', 147, 14, '&nbsp;هغه ستا سرحدونه په سلامتۍ کښې ساتى، او د ټولو نه په ښو غنمو باندې دې معموروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15378, 'Psalms 147:15', 'Psalms', 147, 15, '&nbsp;هغه چې خپل احکام زمکې ته ورولېږى، نو د هغۀ حُکم په منډه خوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15379, 'Psalms 147:16', 'Psalms', 147, 16, '&nbsp;هغه واوره لکه د وړۍ خوروى، او واوره لکه د ايرو په شان زغلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15380, 'Psalms 147:17', 'Psalms', 147, 17, '&nbsp;هغه د کاڼو په شان ږلۍ ورَوى د هغۀ د واورې طوفان ته څوک ټينګېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15381, 'Psalms 147:18', 'Psalms', 147, 18, '&nbsp;هغه خپل کلام رالېږى او واوره پرې ويلى کيږى، هغه خپلې هواګانې رالېږى او اوبۀ ترې راروانې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15382, 'Psalms 147:19', 'Psalms', 147, 19, '&nbsp;هغۀ خپل کلام يعقوب ته ورښکاره کړو، او خپل شريعت او قانون يې بنى اِسرائيلو ته ښکاره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15383, 'Psalms 147:20', 'Psalms', 147, 20, '&nbsp;هغۀ داسې د بل قوم دپاره کړى نۀ دى، هغوئ د دۀ په شريعت نۀ پوهيږى. د مالِک خُدائ ثناء صِفت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15384, 'Psalms 148:1', 'Psalms', 148, 1, '&nbsp;د آسمانونو نه د مالِک خُدائ ثناء صِفت وکړئ، د هغۀ ثناء صِفت په اوچتو آسمانونو کښې وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15385, 'Psalms 148:2', 'Psalms', 148, 2, '&nbsp;د هغۀ ټولو فرښتو د هغۀ ثناء صِفت وکړئ، ټولو آسمانى مخلوقاتو د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15386, 'Psalms 148:3', 'Psalms', 148, 3, '&nbsp;اے نمر او سپوږمۍ د مالِک خُدائ ثناء صِفت وکړئ، ټولو ځلېدونکو ستورو د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15387, 'Psalms 148:4', 'Psalms', 148, 4, '&nbsp;اوچتو آسمانونو د هغۀ ثناء صِفت وکړئ، په آسمان کښې بره اوبو د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15388, 'Psalms 148:5', 'Psalms', 148, 5, '&nbsp;هغوئ ټول دې د مالِک خُدائ د نوم ثناء صِفت وکړى، ځکه چې د هغۀ په حُکم دوئ پېدا شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15389, 'Psalms 148:6', 'Psalms', 148, 6, '&nbsp;او هغوئ يې د تل دپاره په خپل ځايونو مقرر کړې دى، او هغۀ ورته قانون مقرر کړو چې هيڅکله نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15390, 'Psalms 148:7', 'Psalms', 148, 7, '&nbsp;د زمکې نه د مالِک خُدائ ثناء صِفت وکړئ، اے د لويو سمندرونو مخلوقه او د ټولو سمندرونو لاندې بېخ کښې چې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15391, 'Psalms 148:8', 'Psalms', 148, 8, '&nbsp;برېښنا او ږلۍ، واورو او وريځو، طوفانى بادونو چې تاسو د هغۀ حُکم منئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15392, 'Psalms 148:9', 'Psalms', 148, 9, '&nbsp;تاسو غرونو او ټولو غونډو، مېوه دارو ونو او ټولو ديارونو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15393, 'Psalms 148:10', 'Psalms', 148, 10, '&nbsp;ځنګلى ځناورو او ټولو څاروو، ښوئېدونکې مخلوقه، او د هوا مارغانو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15394, 'Psalms 148:11', 'Psalms', 148, 11, '&nbsp;د زمکې بادشاهانو او ټولو قومونو، تاسو ټولو شهزادګانو او د دُنيا بادشاهانو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15395, 'Psalms 148:12', 'Psalms', 148, 12, '&nbsp;اے ټولو ځوانانو او پېغلو، بوډاګانو او ماشومانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15396, 'Psalms 148:13', 'Psalms', 148, 13, '&nbsp;ټول دې د مالِک خُدائ د نوم لوئى بيانوى، ځکه چې صرف د هغۀ نوم لوئ دے، او د هغۀ شان او شوکت په زمکې آسمانونو باندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15397, 'Psalms 148:14', 'Psalms', 148, 14, '&nbsp;هغۀ خپل قوم دپاره د فخر ښکر پورته کړے دے، ترڅو د هغۀ ټول نېک او مقدس خلق د هغۀ ثناء صِفت بيان کړى، يعنې بنى اِسرائيل چې هغۀ ته نزدې دى. د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15398, 'Psalms 149:1', 'Psalms', 149, 1, '&nbsp;د مالِک خُدائ ثناء صِفت بيان کړئ. مالِک خُدائ ته يو نوے سرود ووايئ، د هغۀ ثناء صِفت د هغۀ د مؤمنانو په ډله کښې بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15399, 'Psalms 149:2', 'Psalms', 149, 2, '&nbsp;بنى اِسرائيل دې د خپل خالق سره خوشحالى وکړى، د صيون خلق دې د خپل بادشاه سره خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15400, 'Psalms 149:3', 'Psalms', 149, 3, '&nbsp;هغوئ دې د هغۀ د نوم ثناء صِفت په ګډا کښې بيان کړى، او هغۀ ته دې په تمبل او رباب سره موسيقى وغږوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');